{
30→    public const BOOT = 'scripts/inventory/boot/routes.php';

    public const OPENAPI = 'openapi/vaulter-v1.yaml';

    /** Switches besides `vaulter.features.*` that mount routes; their default is read from the package config. */
    public const EXTRA_FLAGS = ['vaulter-documents.collaboration.enabled' => false];

    private const OPENAPI_METHODS = ['get', 'post', 'put', 'patch', 'delete', 'head', 'options'];

    /** @return Built */
40→    public static function build(Repo $repo): array
    {
        $problems = [];
        foreach (['azgard', 'filament'] as $package) {
            if (is_dir($repo->path("packages/{$package}/routes"))) {
                $problems[] = ['code' => 'unscanned-routes', 'message' => "http: packages/{$package}/routes exists — the boot lists only core, media, drive and documents; add the package to boot/routes.php", 'exit' => 1];
            }
        }

        $flags = [...Config::featureFlags($repo), ...self::EXTRA_FLAGS];
50→        $runs = ['' => []];
        foreach ($flags as $flag => $default) {
            $runs[$flag] = [$flag => !$default];
        }
        $booted = self::boot($repo, $runs);
        $merged = self::merge($booted, $flags);
        $routes = $merged['routes'];
        $requires = $merged['requires'];
        $problems = [...$problems, ...$merged['problems']];
        $inDefaults = self::index($booted['']);
60→
        [$operations, $prefix] = self::openapi($repo);
        $matched = [];
        $items = [];
        foreach ($routes as $id => $route) {
            $path = self::relative($route['uri'], $prefix);
            $operation = null;
            foreach ($route['methods'] as $method) {
                $key = strtoupper($method).' '.$path;
                if ($path !== null && isset($operations[$key])) {
70→                    $operation = $operations[$key];
                    $matched[$key] = true;
                }
            }
            $action = (string) $route['action'];
            $flagsOfRoute = array_values(array_unique($requires[$id] ?? []));
            sort($flagsOfRoute, SORT_STRING);
            $items[] = array_filter([
                'id' => 'route:'.$id,
